import {defineCollection} from 'astro:content';
import {z} from 'astro/zod';
import {docsLoader, i18nLoader} from '@astrojs/starlight/loaders';
import {docsSchema, i18nSchema} from '@astrojs/starlight/schema';

/**
 * The pages of the site. The ones under `plugins/` and `packages/` are generated by tools/sync.ts and carry, besides what Starlight
 * reads, where they come from: the product, the version (line), the state of the translation and the provenance of the page.
 */
export const collections = {
    // The texts of the interface that Starlight draws (src/content/i18n/<language>.json). Starlight already brings most languages.
    i18n: defineCollection({loader: i18nLoader(), schema: i18nSchema()}),
    docs: defineCollection({
        loader: docsLoader(),
        schema: docsSchema({
            extend: z.object({
                product: z.string().optional(),
                line: z.string().optional(),
                status: z.enum(['source', 'translated', 'missing', 'outdated']).optional(),
                provenance: z.enum(['added', 'modified', 'inherited']).optional(),
                provenanceFrom: z.string().optional(),
                shownLang: z.string().optional(),
            }),
        }),
    }),
};
